WITH promo_brand_agg AS ( SELECT i.i_brand, i.i_category, p.p_promo_id, p.p_promo_name, SUM(p.p_cost) AS total_promo_cost, SUM(COALESCE(wr.wr_return_amt,0)) AS total_return_amt, SUM(COALESCE(wr.wr_return_quantity,0)) AS total_return_qty, COUNT(DISTINCT wp.wp_web_page_id) AS distinct_page_cnt FROM promotion p JOIN item i ON i.i_item_sk = p.p_item_sk LEFT JOIN web_returns wr ON wr.wr_item_sk = i.i_item_sk LEFT JOIN web_page wp ON wp.wp_web_page_sk = wr.wr_web_page_sk GROUP BY i.i_brand, i.i_category, p.p_promo_id, p.p_promo_name ) SELECT i_brand, i_category, p_promo_id, p_promo_name, total_promo_cost, total_return_amt, total_return_qty, distinct_page_cnt, CASE WHEN total_promo_cost = 0 THEN NULL ELSE total_return_amt / total_promo_cost END AS return_rate, CASE WHEN total_promo_cost = 0 THEN 'No Cost' WHEN total_return_amt / total_promo_cost < 0.05 THEN 'Excellent' WHEN total_return_amt / total_promo_cost BETWEEN 0.05 AND 0.15 THEN 'Good' ELSE 'Poor' END AS effectiveness, DENSE_RANK() OVER (PARTITION BY i_brand ORDER BY total_return_amt DESC) AS brand_promo_rank, ROW_NUMBER() OVER (PARTITION BY i_brand ORDER BY total_return_amt DESC) AS brand_top_promo_rownum FROM promo_brand_agg WHERE total_promo_cost > 0 ORDER BY i_brand, brand_promo_rank LIMIT 100
